module TopModule (
    input  [4:1] x,
    output       f
);

    // K-map groups:
    // 1) x[3] = 1 and x[1] = 0  ->  x[3] & ~x[1]
    // 2) x[4] = 1 and x[2] = 1  ->  x[4] & x[2]
    assign f = (x[3] & ~x[1]) | (x[4] & x[2]);

endmodule
```

If your testbench uses `x[3:0]` and maps the K-map bits as `x[1]=x[0]`, `x[2]=x[1]`, `x[3]=x[2]`, `x[4]=x[3]`, the equivalent module is:

```verilog
module TopModule (
    input  [3:0] x,
    output       f
);

    wire x1 = x[0];
    wire x2 = x[1];
    wire x3 = x[2];
    wire x4 = x[3];

    assign f = (x3 & ~x1) | (x4 & x2);

endmodule
```
